import{LEVELS,fresh,unlocked,record,finish,recommend,restore,metrics}from'./engine.mjs';
import{CHARACTERS as C,QUESTIONS as Q,DIAGNOSTIC}from'./content.mjs';
import{slidesFor,followingCharacter,resumeIndex}from'./journey.mjs';
import{createPlayer}from'./audio.mjs';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={learn:'M4 5h6q2 0 2 2v14q-2-2-8-2Z M20 5h-6q-2 0-2 2v14q2-2 8-2Z',review:'M4 8a8 8 0 1 1-1 7 M4 3v5h5',progress:'M5 20V12 M12 20V5 M19 20V9',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',close:'m6 6 12 12 M6 18 18 6',play:'M4 9h4l5-4v14l-5-4H4Z M17 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',stop:'M7 7h10v10H7Z',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',leaf:'M19 3C3 2 1 15 8 19c7 4 15-3 11-16Z M6 21 17 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`;
let state=fresh(),storageOK=true;
try{const raw=localStorage.getItem('reading-paths-v1');if(raw)state=restore(raw);}catch{storageOK=false;}
let filter='all',search='',lessonIndex=0,activeCharacter=null,quiz=null;
const audioItems=new Map();
const player=createPlayer({onState:key=>{document.querySelectorAll('[data-audio]').forEach(b=>{const playing=b.dataset.audio===key;b.classList.toggle('playing',playing);b.setAttribute('aria-pressed',String(playing));b.innerHTML=icon(playing?'stop':'play')+`<span>${playing?'Stop':'Listen'}</span>`;});},onError:toast});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function applyPrefs(){document.documentElement.dataset.size=state.preferences.size;document.documentElement.dataset.motion=state.preferences.motion;}
function save(){try{localStorage.setItem('reading-paths-v1',JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Progress cannot be saved in this browser. Export a backup before leaving.');}applyPrefs();}
applyPrefs();
const phon=r=>state.preferences.notation==='none'?'':state.preferences.notation==='both'?`${esc(r.pinyin)}<span class="zhuyin">${esc(r.zhuyin)}</span>`:esc(r[state.preferences.notation]);
const choicePhon=r=>state.preferences.notation==='none'?esc(r.pinyin):phon(r);
const questions=id=>Q.filter(q=>q.characterId===id);
const mode=()=>state.learningMode==='explore'?'explore':'guided';
const outstanding=()=>Object.values(state.mistakes).filter(m=>m.correctStreak<2);
const route=()=>location.hash.slice(1).split('/').filter(Boolean);
const pct=n=>n===null?'—':`${Math.round(n)}%`;
function go(path){player.stop();if(location.hash===`#/${path}`)render();else location.hash=`/${path}`;}
function nextAvailable(){const resume=C.find(c=>c.id===state.resume?.characterId);if(resume&&(mode()==='explore'||unlocked(state,resume.level))&&!state.lessons[resume.id]?.passed&&(state.resume.index<slidesFor(resume).length||questions(resume.id).length))return resume;return C.find(c=>(mode()==='explore'||unlocked(state,c.level))&&(questions(c.id).length?!state.lessons[c.id]?.passed:!state.viewed?.[c.id]))||C.find(c=>mode()==='explore'||unlocked(state,c.level))||C[0];}
function playButton(item,label){audioItems.set(item.key,item);return`<button class="listen" data-audio="${esc(item.key)}" aria-label="Play ${esc(label||item.text)} in Taiwan Mandarin" aria-pressed="false">${icon('play')}<span>Listen</span></button>`;}
const readingAudio=(c,r)=>playButton({key:`reading:${r.id}`,text:c.char,kind:'character'},`${c.char}, ${r.pinyin}`);
const wordAudio=(r,w)=>playButton({key:`word:${r.id}:${w.text}`,text:w.text,kind:'word'},w.text);
const sentenceAudio=s=>playButton({key:`sentence:${s.source.textId}:${s.target}`,text:s.text,kind:'sentence'},'this sentence');

function shell(body,{active='learn',session=false,dock='',title=''}={}){
 audioItems.forEach((_,key)=>{if(audioItems.size>300)audioItems.delete(key);});
 document.body.dataset.session=String(session);
 $('#app').innerHTML=`<div class="app-frame"><header class="app-header">${session?`<button class="icon-btn" data-action="leave-session" aria-label="Leave ${quiz&&route()[0]==='quiz'?'check':'lesson'}">${icon('close')}</button><span class="session-title">${esc(title)}</span>`:'<a class="brand" href="#/home"><span class="brand-mark" lang="zh-Hant">字</span><span>Reading Paths<small>一字多讀</small></span></a>'}<button class="icon-btn" data-action="settings" aria-label="Display and audio settings">${icon('settings')}</button></header><main id="main" tabindex="-1" class="${session?'session-main':'page-main'}">${body}</main>${session?dock:`<nav class="bottom-nav" aria-label="Main navigation">${[['learn','Learn','home'],['review','Review','review'],['progress','Progress','profile']].map(([id,label,path])=>`<a href="#/${path}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='review'&&outstanding().length?`<i>${outstanding().length}</i>`:''}</a>`).join('')}</nav>`}</div>`;
}
function dock(primary,action,{back='',secondary='',extra=''}={}){return`<div class="session-dock">${back?`<button class="icon-btn back-control" data-action="${back}" aria-label="Previous learning card">${icon('back')}</button>`:''}<button class="btn primary" data-action="${action}" ${extra}>${primary}${icon('arrow')}</button>${secondary}</div>`;}
function intro(){shell(`<section class="intro"><div class="intro-mark" lang="zh-Hant">好</div><p class="eyebrow">One character. A new connection.</p><h1>Learn one sound<br>at a time.</h1><p class="lead">A character can sound different in different words. Discover each reading, one small step at a time.</p><div class="mini-path"><span>字 <small>Character</small></span><i>→</i><span>詞 <small>Word</small></span><i>→</i><span>句 <small>Sentence</small></span></div><button class="btn primary wide" data-action="diagnostic">Find a starting point ${icon('arrow')}</button><button class="text-btn wide" data-action="choose-start">Choose my own start</button><p class="fine-print">6 sample questions · no timer<br>A learning suggestion, rather than an official TBCL assessment.</p></section>`);}
function chooseStart(){shell(`<a class="back-link" href="#/home">${icon('back')} Back</a><p class="eyebrow">Your pace, your choice</p><h1>Where would you<br>like to begin?</h1><p class="lead">Choose a stage. Earlier stages stay open, and Free explore is always available.</p><label class="field"><span>Starting stage</span><select id="start-choice">${LEVELS.map(l=>`<option value="${l}" ${state.start===l?'selected':''}>TBCL ${l}</option>`).join('')}</select></label><button class="btn primary wide" data-action="accept-manual">Start learning ${icon('arrow')}</button>`);}
function home(){const c=nextAvailable(),resume=state.resume?.characterId===c.id&&state.resume.index>0;const ready=mode()==='guided'?LEVELS.find(l=>unlocked(state,l)&&!state.stagePasses.includes(l)&&C.some(c=>c.level===l)&&C.filter(c=>c.level===l).every(c=>questions(c.id).length?state.lessons[c.id]?.passed:state.viewed?.[c.id])):null;shell(`<div class="page-heading"><p class="eyebrow">${state.name==='Learner'?'Your next connection':`Welcome, ${esc(state.name)}`}</p><h1>A little learning.<br>One clear next step.</h1></div><div class="mode-switch" aria-label="Learning mode"><button data-mode="guided" aria-pressed="${mode()==='guided'}">Guided path</button><button data-mode="explore" aria-pressed="${mode()==='explore'}">Free explore</button></div><section class="next-card">${ready?`<span class="badge">STAGE ${ready} · UP NEXT</span><div class="hero-character">${ready}</div><h2>Bring your connections together.</h2><p>You explored the sample characters here.<br>Pass the stage review to open the next stage.</p><button class="btn primary wide" data-action="stage-quiz" data-level="${ready}">Review stage ${ready} ${icon('arrow')}</button>`:`<span class="badge">TBCL ${c.level} · ${resume?'CONTINUE':'UP NEXT'}</span><div class="hero-character" lang="zh-Hant">${c.char}</div><div class="phonetics reading-pair">${c.readings.map(phon).filter(Boolean).join('<span class="divider">/</span>')}</div><h2>${c.title}</h2><p>Character → words → sentence<br>One card at a time.</p><button class="btn primary wide" data-lesson="${c.id}">${resume?'Continue this character':'Learn this character'} ${icon('arrow')}</button>`}</section><div class="home-links"><button class="link-row" data-action="collection"><span>Explore the characters<small>Choose what to learn next</small></span>${icon('arrow')}</button><button class="link-row" data-action="path"><span>Your guided path<small>Stage reviews and unlocks</small></span>${icon('arrow')}</button></div><details class="quiet-details"><summary>About this sample course</summary><p>5 character previews, 4 five-question checks, and 2 COCT sentence candidates. Full lessons are still being reviewed. Your learning records stay in this browser.</p></details>`);}
function collection(){const list=C.filter(c=>(filter==='all'||c.level===filter)&&(!search||`${c.char} ${c.title} ${c.readings.map(r=>r.pinyin).join(' ')}`.toLowerCase().includes(search.toLowerCase())));shell(`<a href="#/home" class="back-link">${icon('back')} Back to learning</a><p class="eyebrow">Free to be curious</p><h1>Choose a character.</h1><p class="lead">${mode()==='guided'?'Follow the guided stages, or switch to Free explore.':'Every sample character is open. Your progress is shared with the guided path.'}</p><div class="mode-switch"><button data-mode="guided" aria-pressed="${mode()==='guided'}">Guided path</button><button data-mode="explore" aria-pressed="${mode()==='explore'}">Free explore</button></div><div class="filters" aria-label="Filter by stage">${['all',...LEVELS].map(l=>`<button class="pill ${filter===l?'active':''}" data-filter="${l}" aria-pressed="${filter===l}">${l==='all'?'All':l}</button>`).join('')}</div><input class="search" id="search" aria-label="Search characters" placeholder="Search character or Pinyin" value="${esc(search)}"><div class="character-grid">${list.map(c=>`<button class="character-card" data-lesson="${c.id}"><span class="card-top">TBCL ${c.level}${state.lessons[c.id]?.passed?icon('check'):mode()==='guided'&&!unlocked(state,c.level)?icon('lock'):''}</span><span class="card-character" lang="zh-Hant">${c.char}</span><span class="phonetics">${c.readings.map(phon).filter(Boolean).join(' / ')}</span><small>${questions(c.id).length?'Sample lesson':'Preview · quiz pending'}</small></button>`).join('')}</div>${!list.length?'<div class="empty"><h2>More lessons are coming.</h2><p>This stage is waiting for reviewed content.</p><button class="btn secondary" data-filter="all">See available characters</button></div>':''}`);}
function pathPage(){shell(`<a href="#/home" class="back-link">${icon('back')} Back to learning</a><p class="eyebrow">A little structure</p><h1>Your guided path.</h1><p class="lead">Pass a stage review to open the next stage. You can also explore freely at any time.</p><div class="stage-list">${LEVELS.map(l=>`<button class="stage-row" data-stage="${l}"><span class="stage-circle ${unlocked(state,l)?'open':''}">${l}</span><span><b>TBCL ${l}</b><small>${state.stagePasses.includes(l)?'Review passed':unlocked(state,l)?'Open to learn':'Locked in guided path'}</small></span>${icon(state.stagePasses.includes(l)?'check':unlocked(state,l)?'arrow':'lock')}</button>`).join('')}</div>`);}
function stagePage(l){const open=unlocked(state,l),list=C.filter(c=>c.level===l),previous=LEVELS[Math.max(0,LEVELS.indexOf(l)-1)];shell(`<a href="#/path" class="back-link">${icon('back')} Back to your path</a><p class="eyebrow">${open?'A connection at a time':'Guided path · locked'}</p><h1>TBCL ${esc(l)}</h1><p class="lead">${open?'Choose a character, or check what you already know.':'Explore this stage freely, or pass the previous stage review to open it in your guided path.'}</p>${!open?`<button class="btn primary wide" data-action="explore-stage" data-level="${l}">Explore this stage freely ${icon('arrow')}</button>`:''}<div class="character-grid">${list.map(c=>`<button class="character-card" data-lesson="${c.id}"><span class="card-top">TBCL ${c.level}</span><span class="card-character" lang="zh-Hant">${c.char}</span><small>${c.title}</small></button>`).join('')}</div>${!list.length?'<div class="empty"><p>No reviewed sample lessons at this stage yet.</p></div>':''}<button class="btn ${open?'primary':'secondary'} wide" data-action="stage-quiz" data-level="${open?l:previous}">${open?'Try the stage review':'Challenge the previous stage review'} ${icon('arrow')}</button><p class="fine-print">Sample stage reviews use the available sample questions.<br>They do not certify a TBCL level.</p>`);}
function openLesson(id,{restart=false}={}){const c=C.find(c=>c.id===id);if(!c)return;activeCharacter=id;lessonIndex=restart?0:resumeIndex(c,state.resume);quiz=null;go('lesson/'+id);}
function lesson(id){const c=C.find(c=>c.id===id);if(!c)return go('home');if(mode()==='guided'&&!unlocked(state,c.level))return stagePage(c.level);if(activeCharacter!==id){activeCharacter=id;lessonIndex=resumeIndex(c,state.resume);}const slides=slidesFor(c);lessonIndex=Math.max(0,Math.min(lessonIndex,slides.length));state.resume={characterId:id,index:lessonIndex};if(lessonIndex===slides.length){state.viewed??={};state.viewed[id]=true;}save();if(lessonIndex===slides.length)return lessonEnd(c);const slide=slides[lessonIndex],r=slide.reading;let content='',kindLabel=slide.kind==='character'?'Character':slide.kind==='word'?'Word':'Sentence';
 if(slide.kind==='character')content=`<p class="eyebrow">Reading ${slide.readingIndex+1} of ${c.readings.length}</p><div class="focus-character" lang="zh-Hant">${c.char}</div><div class="phonetics focus-phonetics">${phon(r)||'Pronunciation hints hidden'}</div>${readingAudio(c,r)}<h1 class="meaning">${esc(r.meaning)}</h1><p class="teaching-tip">${slide.readingIndex===0?'Start with this reading. Next, see it inside a word.':'Same character, a different sound and meaning. Next, meet its words.'}</p>`;
 if(slide.kind==='word'){const w=slide.word;content=`<p class="eyebrow">Meet a word · Word level ${w.level}</p><div class="focus-word zh" lang="zh-Hant">${esc(w.text)}</div><div class="phonetics focus-phonetics">${phon(w)}</div>${wordAudio(r,w)}<h1 class="meaning">${esc(w.gloss)}</h1><p class="teaching-tip">${state.preferences.notation==='none'?'Notice how the character works in this word.':`Here, <span lang="zh-Hant">${c.char}</span> is read <b>${phon(r)}</b>.`}</p><details class="quiet-details"><summary>Word source</summary><p>NAER TBCL wordlist · worksheet row ${w.source.row}. Word and character levels are tracked separately.</p></details>`;}
 if(slide.kind==='sentence'){const s=slide.sentence;content=`<p class="eyebrow">Hear it in a sentence</p><p class="focus-sentence zh" lang="zh-Hant">${esc(s.text).replace(esc(s.target),`<mark>${esc(s.target)}</mark>`)}</p>${sentenceAudio(s)}<p class="teaching-tip">Find <span class="inline-zh" lang="zh-Hant">${esc(s.target)}</span>. Connect its meaning to the reading you just learned.</p><details class="quiet-details"><summary>COCT source · review candidate</summary><p>${esc(s.source.corpus)} · text ${esc(s.source.textId)}. Query ${s.source.queryId}, result ${s.source.rank}. Original wording retained; teaching suitability is awaiting review.</p><a href="${s.source.url}" target="_blank" rel="noopener">Open COCT ↗</a></details>`;}
 if(slide.kind==='sentence-pending')content=`<p class="eyebrow">Sentence · coming next</p><div class="pending-mark" lang="zh-Hant">${c.char}</div><h1 class="meaning">A real example<br>is on its way.</h1><p class="teaching-tip">${esc(r.note||'A COCT sentence for this reading is still being selected. Keep going to the next reading or the character check.')}</p><span class="status-chip">Example pending</span>`;
 const next=slides[lessonIndex+1];const label=!next?'Finish this character':next.kind==='character'?'Meet the next reading':next.kind==='word'?'Next word':'Next: a sentence';
 shell(`<div class="session-progress"><div><span>TBCL ${c.level} · <span lang="zh-Hant">${c.char}</span></span><span>${lessonIndex+1} / ${slides.length}</span></div><div class="progress-track" role="progressbar" aria-label="Lesson progress" aria-valuemin="0" aria-valuemax="${slides.length}" aria-valuenow="${lessonIndex+1}"><span style="width:${100*(lessonIndex+1)/slides.length}%"></span></div></div><div class="learning-phase"><span class="${kindLabel==='Character'?'active':''}">Character</span><i>→</i><span class="${kindLabel==='Word'?'active':''}">Word</span><i>→</i><span class="${kindLabel==='Sentence'?'active':''}">Sentence</span></div><article class="focus-card" key="${slide.id}">${content}</article>`,{session:true,title:`Learning · ${kindLabel}`,dock:dock(label,'next-card',{back:lessonIndex?'previous-card':''})});}
function nextFor(c){return followingCharacter(C,c.id,state,mode(),unlocked);}
function continuation(c){const next=nextFor(c);return next?{label:`Next character: ${next.char}`,action:'next-character',extra:`data-id="${next.id}"`}:{label:`Review stage ${c.level}`,action:'stage-quiz',extra:`data-level="${c.level}"`};}
function lessonEnd(c){const ready=questions(c.id).length,next=continuation(c);shell(`<section class="result-card"><span class="result-mark">${icon('check')}</span><p class="eyebrow">Character explored</p><h1>One character.<br>More connections.</h1><div class="end-readings">${c.readings.map(r=>`<div><span class="end-character" lang="zh-Hant">${c.char}</span><span><b>${phon(r)||'Reading explored'}</b><small>${esc(r.meaning)}</small></span>${readingAudio(c,r)}</div>`).join('')}</div><p class="lead">${ready?'Try five short questions to check these reading connections.':'The check for this character is still being prepared. You can continue learning.'}</p><button class="text-btn" data-action="restart-character" data-id="${c.id}">Explore this character again</button></section>`,{session:true,title:'Learning · Character complete',dock:ready?dock('Try the 5-question check','lesson-quiz',{extra:`data-id="${c.id}"`}):dock(next.label,next.action,{extra:next.extra,back:'previous-card'})});}
function startQuiz(type,id){let qs=type==='diagnostic'?DIAGNOSTIC:type==='lesson'?questions(id):type==='stage'?Q.filter(q=>C.find(c=>c.id===q.characterId).level===id):id?[Q.find(q=>q.id===id)].filter(Boolean):outstanding().filter(m=>m.due<=Date.now()).map(m=>Q.find(q=>q.id===m.questionId)).filter(Boolean);if(!qs.length){toast(type==='stage'?'This stage review is waiting for reviewed questions.':'No review questions are due right now.');return;}player.stop();quiz={type,id,questions:qs,index:0,score:0,answered:false,chosen:null,done:false};go('quiz');}
function quizPage(){if(!quiz)return go(state.onboarded?'home':'start');if(quiz.done)return result();const t=quiz,q=t.questions[t.index],c=C.find(c=>c.id===q.characterId);shell(`<div class="session-progress"><div><span>${t.type==='diagnostic'?'Starting check':t.type==='stage'?`Stage ${t.id} review`:t.type==='review'?'Review':`${c.char} · Character check`}</span><span>${t.index+1} / ${t.questions.length}</span></div><div class="progress-track" role="progressbar" aria-label="Check progress" aria-valuemin="0" aria-valuemax="${t.questions.length}" aria-valuenow="${t.index+1}"><span style="width:${100*(t.index+1)/t.questions.length}%"></span></div></div><section class="question-card"><p class="eyebrow">Choose a reading</p><h1 class="question-heading">How is <span lang="zh-Hant">${c.char}</span><br>read in this word?</h1><div class="quiz-word zh" lang="zh-Hant">${esc(q.word)}</div><div class="answers">${c.readings.map((r,i)=>`<button class="answer ${t.answered&&r.id===q.readingId?'correct':t.answered&&r.id===t.chosen?'incorrect':''}" data-answer="${r.id}" ${t.answered?'disabled':''}><span>${String.fromCharCode(65+i)}</span><b>${choicePhon(r)}</b>${t.answered&&r.id===q.readingId?icon('check'):''}</button>`).join('')}</div>${t.answered?`<div class="feedback ${t.chosen===q.readingId?'':'wrong'}" role="status"><h2>${t.chosen===q.readingId?'That connection fits.':'A useful one to revisit.'}</h2><p>${esc(q.explanation)} ${t.type!=='diagnostic'&&t.chosen!==q.readingId?'Saved in Review.':''}</p></div>`:'<p class="fine-print">Take your time. Choose one answer.</p>'}${state.preferences.notation==='none'?'<p class="fine-print">Reading choices stay visible during pronunciation questions.</p>':''}</section>`,{session:true,title:t.type==='diagnostic'?'Find your starting point':'Check your connection',dock:t.answered?dock(t.index+1===t.questions.length?'See your result':'Next question','next-question'):'<div class="session-dock"><p class="dock-hint">Choose an answer to continue.</p></div>'});if(t.answered)document.querySelector('.session-dock .btn')?.focus({preventScroll:true});}
function result(){const t=quiz,pass=t.score/t.questions.length>=.8;if(t.type==='diagnostic'){const l=recommend(t.score,t.questions.length);shell(`<section class="result-card"><p class="eyebrow">A starting suggestion</p><h1>Start where<br>it feels right.</h1><div class="result-score">${l}</div><h2>Suggested stage · TBCL ${l}</h2><p class="lead">${t.score} of ${t.questions.length} sample questions correct. This suggests where to begin these lessons; it is not a TBCL proficiency result.</p><label class="field"><span>Your starting stage</span><select id="result-start">${LEVELS.map(x=>`<option value="${x}" ${x===l?'selected':''}>TBCL ${x}</option>`).join('')}</select></label><p class="fine-print">Choose a different stage if you prefer.<br>You can change it later.</p></section>`,{session:true,title:'Your starting point',dock:dock('Start learning','accept-start')});return;}
 const c=t.type==='lesson'?C.find(c=>c.id===t.id):null,next=c?continuation(c):null;
 let action='result-home',label='Back to learning',extra='';if(c&&pass){({label,action,extra}=next);}else if(c){action='restart-character';label=`Relearn ${c.char}`;extra=`data-id="${c.id}"`;}else if(t.type==='stage'&&pass){const nextStage=LEVELS[LEVELS.indexOf(t.id)+1],first=C.find(c=>c.level===nextStage);if(first){action='next-character';label=`Next character: ${first.char}`;extra=`data-id="${first.id}"`;}}
 shell(`<section class="result-card"><span class="result-mark">${icon(pass?'check':'review')}</span><p class="eyebrow">${t.type==='review'?'Review saved':pass?'A step forward':'Progress includes coming back'}</p><h1>${t.type==='review'?'Keep the connection<br>growing.':pass?'Nicely connected.':'Let’s revisit<br>a few.'}</h1><div class="result-score">${t.score}<small> / ${t.questions.length}</small></div><p class="lead">${t.type==='review'?'One correct revisit schedules the next for tomorrow. Two correct answers move an item out of active review.':t.type==='stage'?(pass?'Stage review passed. The next stage is now open.':'Aim for 80% to pass. Your missed connections are saved in Review.'):(pass?'Character check passed. Your progress is shared with Free explore and the guided path.':'Aim for 4 out of 5 to pass. Your missed connections are saved in Review.')}</p><a class="text-btn" href="#/review">${outstanding().length?'Revisit missed connections':'Open your review space'}</a>${t.type!=='review'?'<button class="text-btn" data-action="retry">Try this check again</button>':''}</section>`,{session:true,title:'Your result',dock:dock(label,action,{extra})});}
function review(){const items=Object.values(state.mistakes).sort((a,b)=>a.due-b.due),due=items.filter(m=>m.correctStreak<2&&m.due<=Date.now());shell(`<p class="eyebrow">Your review space</p><h1>A fresh look.<br>A stronger connection.</h1><p class="lead">Come back to the exact word and reading that needs practice.</p>${items.length?`<button class="btn primary wide" data-action="review-quiz" ${!due.length?'disabled':''}>${due.length?`Review ${due.length} due connection${due.length===1?'':'s'}`:'You’re up to date'} ${icon('arrow')}</button><div class="review-list">${items.map(m=>{const q=Q.find(q=>q.id===m.questionId);if(!q)return'';const c=C.find(c=>c.id===q.characterId),r=c.readings.find(r=>r.id===q.readingId);const w=r.words.find(w=>q.word.startsWith(w.text));return`<article class="review-item"><div class="review-word"><div><p class="zh" lang="zh-Hant">${esc(q.word)}</p><div class="phonetics">${phon(r)}</div></div>${w?wordAudio(r,w):''}</div><p class="fine-print">${m.wrongCount} missed attempt${m.wrongCount===1?'':'s'} · ${m.correctStreak>=2?'Revisited twice':m.due>Date.now()?`Next revisit ${new Date(m.due).toLocaleDateString('en-US',{month:'short',day:'numeric'})}`:'Ready to revisit'}</p><div class="split-buttons"><button class="btn secondary" data-relearn="${c.id}">Relearn</button><button class="btn secondary" data-review-id="${q.id}">Practise ${icon('arrow')}</button></div></article>`;}).join('')}</div><details class="quiet-details"><summary>How review works</summary><p>Wrong answers are saved by character, reading and word. One correct revisit schedules another for tomorrow; two correct answers move it out of active review. This sample repeats the original question, so the record indicates practice rather than validated mastery.</p></details>`:'<div class="empty"><span class="result-mark">'+icon('review')+'</span><h2>A clear space for now.</h2><p>Words you miss in a check will appear here, ready to revisit.</p><a class="btn primary" href="#/home">Keep learning '+icon('arrow')+'</a></div>'}`,{active:'review'});}
function profile(){const m=metrics(state),completed=Object.values(state.lessons).filter(l=>l.passed).length;shell(`<p class="eyebrow">Your progress</p><h1>See your connections<br>grow.</h1><div class="metric-grid"><article><strong>${pct(m.accuracy)}</strong><h2>Overall accuracy</h2><p>${m.answerCount} practice answers<br>Includes repeat answers</p></article><article><strong>${pct(m.quizAverage)}</strong><h2>Average quiz score</h2><p>${m.quizCount} completed character quizzes<br>Includes retakes</p></article></div><details class="quiet-details"><summary>What these numbers mean</summary><p>Overall accuracy = correct practice answers ÷ all practice answers. Average quiz score = the mean percentage of your completed character quizzes. Stage reviews, starting checks and review sessions are excluded from that quiz average. Starting checks are excluded from both metrics.</p><p>First-attempt accuracy: <b>${pct(m.firstAccuracy)}</b> across ${m.firstCount} different questions. It counts each question’s first practice answer once.</p>${!m.quizCount&&Object.keys(state.lessons).length?'<p>Earlier best scores are preserved below. Average quiz score starts with newly recorded quizzes.</p>':''}</details><div class="progress-summary"><span><b>${completed}</b> character checks passed</span><span><b>${state.stagePasses.length}</b> stage reviews passed</span></div><h2 class="section-title">Your characters</h2><div class="score-list">${C.map(c=>{const qs=state.attempts.filter(a=>a.characterId===c.id&&a.mode!=='diagnostic'),l=state.lessons[c.id];return`<div><span class="score-char" lang="zh-Hant">${c.char}</span><span><b>${l?`Best ${l.best}/${l.total}`:'No quiz completed'}</b><small>${qs.length?`${Math.round(100*qs.filter(a=>a.correct).length/qs.length)}% correct · ${qs.length} answers`:'Not practised yet'}</small></span>${l?.passed?icon('check'):''}</div>`;}).join('')}</div><details class="settings-section"><summary>Your learning setup</summary><form id="profile-form"><label class="field"><span>Preferred name</span><input id="learner-name" value="${esc(state.name)}" maxlength="60" autocomplete="nickname"></label><label class="field"><span>Starting stage</span><select id="profile-start">${LEVELS.map(l=>`<option value="${l}" ${l===state.start?'selected':''}>TBCL ${l}</option>`).join('')}</select></label><button class="btn secondary wide" type="submit">Save profile</button></form><button class="text-btn wide" data-action="diagnostic">Retake starting check</button></details><details class="settings-section"><summary>Keep a backup</summary><p>Progress is saved in this browser. A backup lets you move it to another device. Import replaces your local copy after confirmation.</p><div class="split-buttons"><button class="btn secondary" data-action="export">Export</button><button class="btn secondary" data-action="import">Import</button></div><input id="backup-file" type="file" accept="application/json,.json" hidden></details><p class="fine-print">${storageOK?'Saved in this browser · no cloud account yet':'Browser storage unavailable · export a backup'}</p>`,{active:'progress'});}
function settings(){const d=$('#settings');d.className='settings-dialog';d.innerHTML=`<div class="dialog-heading"><h2 id="settings-title">Make it comfortable.</h2><button class="icon-btn" data-action="close-settings" aria-label="Close settings">${icon('close')}</button></div><fieldset><legend>Text size</legend><div class="choice-row">${['small','medium','large'].map(x=>`<button class="pill" data-pref="size" data-value="${x}" aria-pressed="${state.preferences.size===x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></fieldset><fieldset><legend>Pronunciation hints</legend><div class="choice-row">${[['pinyin','Pinyin'],['zhuyin','Zhuyin 注音'],['both','Both'],['none','Hide']].map(([x,label])=>`<button class="pill" data-pref="notation" data-value="${x}" aria-pressed="${state.preferences.notation===x}">${label}</button>`).join('')}</div></fieldset><fieldset><legend>Playback speed</legend><div class="choice-row">${[['normal','Normal'],['slow','Slow']].map(([x,label])=>`<button class="pill" data-pref="speed" data-value="${x}" aria-pressed="${state.preferences.speed===x}">${label}</button>`).join('')}</div></fieldset><fieldset><legend>Motion</legend><div class="choice-row">${[['system','Follow device'],['reduced','Reduce motion']].map(([x,label])=>`<button class="pill" data-pref="motion" data-value="${x}" aria-pressed="${state.preferences.motion===x}">${label}</button>`).join('')}</div></fieldset><div class="settings-preview"><span class="zh" lang="zh-Hant">快樂</span><div class="phonetics">${phon(C[2].readings[0].words[0])}</div>${wordAudio(C[2].readings[0],C[2].readings[0].words[0])}</div><details class="quiet-details"><summary>About Taiwan Mandarin audio</summary><p>Recordings are attributed to the MOE Concised Mandarin Dictionary. Other playback uses a Taiwan Mandarin voice available on your device. If none is available, we will ask you to add one instead of switching accents. Speech synthesis and the content still need pronunciation review.</p><p>Recording attribution and original licence: <a href="./audio/README.md" target="_blank" rel="noopener">audio sources</a> · <a href="./audio/LICENSE-MOE.pdf" target="_blank" rel="noopener">MOE terms</a>.</p></details><button class="btn primary wide" data-action="close-settings">Done</button>`;if(!d.open)d.showModal();}
function render(){const[page,id]=route();if(page==='quiz'){quizPage();return;}if(!state.onboarded){if(page==='choose-start')chooseStart();else intro();return;}if(page==='lesson')lesson(id);else if(page==='learn'||page==='explore')collection();else if(page==='path')pathPage();else if(page==='stage'&&LEVELS.includes(id))stagePage(id);else if(page==='review')review();else if(page==='profile')profile();else if(page==='choose-start')chooseStart();else home();}

document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.audio){const item=audioItems.get(d.audio);if(item)player.play(item,state.preferences.speed);return;}
 if(d.pref){player.stop();state.preferences[d.pref]=d.value;save();render();settings();return;}
 if(d.mode){state.learningMode=d.mode;save();render();return;}
 if(d.filter){filter=d.filter;render();return;}
 if(d.stage){go('stage/'+d.stage);return;}
 if(d.lesson){openLesson(d.lesson);return;}
 if(d.relearn){state.learningMode='explore';save();openLesson(d.relearn,{restart:true});return;}
 if(d.reviewId){startQuiz('review',d.reviewId);return;}
 if(d.answer&&quiz&&!quiz.answered){const q=quiz.questions[quiz.index];quiz.chosen=d.answer;quiz.answered=true;if(d.answer===q.readingId)quiz.score++;if(quiz.type!=='diagnostic'){state=record(state,q,d.answer===q.readingId,quiz.type);save();}quizPage();return;}
 switch(d.action){
 case'settings':settings();break;
 case'close-settings':player.stop();$('#settings').close();break;
 case'choose-start':go('choose-start');break;
 case'accept-manual':state.start=$('#start-choice').value;state.onboarded=true;save();openLesson(nextAvailable().id);break;
 case'accept-start':state.recommended=recommend(quiz.score,quiz.questions.length);state.start=$('#result-start').value;state.onboarded=true;save();openLesson(nextAvailable().id);break;
 case'diagnostic':startQuiz('diagnostic');break;
 case'collection':go('learn');break;
 case'path':go('path');break;
 case'explore-stage':state.learningMode='explore';save();go('stage/'+d.level);break;
 case'next-card':player.stop();lessonIndex++;render();$('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});break;
 case'previous-card':player.stop();lessonIndex=Math.max(0,lessonIndex-1);render();window.scrollTo({top:0,behavior:'instant'});break;
 case'restart-character':openLesson(d.id,{restart:true});break;
 case'next-character':openLesson(d.id,{restart:true});break;
 case'lesson-quiz':startQuiz('lesson',d.id);break;
 case'stage-quiz':startQuiz('stage',d.level);break;
 case'review-quiz':startQuiz('review');break;
 case'leave-session':if(route()[0]==='quiz'&&quiz&&!quiz.done){if(!confirm('Leave this check? Practice answers are saved, but an unfinished score will not count.'))break;quiz=null;}go('home');break;
 case'next-question':if(!quiz?.answered)break;if(++quiz.index>=quiz.questions.length){quiz.done=true;if(['lesson','stage'].includes(quiz.type)){state=finish(state,quiz.type,quiz.id,quiz.score,quiz.questions.length);save();}result();}else{quiz.answered=false;quiz.chosen=null;quizPage();}window.scrollTo({top:0,behavior:'instant'});break;
 case'retry':startQuiz(quiz.type,quiz.id);break;
 case'result-home':go('home');break;
 case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='reading-paths-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup exported. Keep it somewhere safe.');break;}
 case'import':$('#backup-file').click();break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const pos=e.target.selectionStart;collection();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();state.name=$('#learner-name').value.trim()||'Learner';state.start=$('#profile-start').value;save();profile();toast('Your profile is saved.');}});
document.addEventListener('change',async e=>{if(e.target.id==='backup-file'&&e.target.files[0])try{const file=e.target.files[0];if(file.size>5000000)throw Error('This backup is too large.');const imported=restore(await file.text());if(confirm('Replace the learning progress saved in this browser with this backup?')){player.stop();state=imported;activeCharacter=null;save();render();toast('Your backup has been restored.');}}catch(error){toast(error.message||'This backup could not be imported.');}});
$('#settings').addEventListener('close',()=>player.stop());
addEventListener('hashchange',()=>{player.stop();render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});});
addEventListener('pagehide',()=>player.stop());
document.addEventListener('visibilitychange',()=>{if(document.hidden)player.stop();});
render();
